namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private readonly Lock _lock = new();
    private readonly List<Notification> _notifications = [];
    private int _nextId = 1;

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.Add(new(_nextId++, "Welcome to the app!", DateTime.UtcNow.AddMinutes(-10)));
        _notifications.Add(new(_nextId++, "Your profile was updated.", DateTime.UtcNow.AddMinutes(-5)));
        _notifications.Add(new(_nextId++, "New feature: dark mode is available.", DateTime.UtcNow.AddMinutes(-2)));
    }

    /// <summary>Returns all notifications ordered newest-first.</summary>
    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return [.. _notifications.OrderByDescending(n => n.Timestamp)];
        }
    }

    /// <summary>Returns notifications added after the given timestamp.</summary>
    public List<Notification> GetSince(DateTime since)
    {
        lock (_lock)
        {
            return [.. _notifications
                .Where(n => n.Timestamp > since)
                .OrderByDescending(n => n.Timestamp)];
        }
    }

    /// <summary>Simulates an incoming notification (called by a background generator).</summary>
    public void Add(string message)
    {
        lock (_lock)
        {
            _notifications.Add(new(_nextId++, message, DateTime.UtcNow));
        }
    }
}

namespace NotificationsApp.Services;

/// <summary>
/// Background service that adds a fake notification every 8 seconds
/// so there is something new for the polling loop to pick up.
/// </summary>
public class NotificationGenerator(NotificationService notifications) : BackgroundService
{
    private static readonly string[] Messages =
    [
        "Deployment to production succeeded.",
        "CPU usage spike detected on server-03.",
        "User 'jdoe' just signed up.",
        "Backup completed successfully.",
        "New comment on issue #42.",
        "Security scan finished — no vulnerabilities found.",
        "Disk usage on db-primary exceeded 80%.",
        "Monthly report is ready for download.",
    ];

    private int _index;

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(8), stoppingToken);
            notifications.Add(Messages[_index % Messages.Length]);
            _index++;
        }
    }
}

@page "/notifications"
@rendermode @(new InteractiveServerRenderMode(prerender: true))
@implements IDisposable
@inject NotificationsApp.Services.NotificationService NotificationService

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>
                    <strong>#@n.Id</strong> &mdash; @n.Message
                </div>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<NotificationsApp.Services.Notification> _notifications = [];
    private CancellationTokenSource? _cts;

    // Runs during SSR *and* when the component becomes interactive.
    // The first call populates the list that gets into the prerendered HTML.
    protected override void OnInitialized()
    {
        _notifications = NotificationService.GetAll();
    }

    // Called only once after the component is interactive in the browser.
    // This is where we start the polling loop — never during static SSR.
    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct);

            var latest = _notifications.Count > 0
                ? _notifications.Max(n => n.Timestamp)
                : DateTime.MinValue;

            var newer = NotificationService.GetSince(latest);

            if (newer.Count > 0)
            {
                // Prepend new items (newest first).
                _notifications.InsertRange(0, newer);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

