+namespace NotificationsApp.Services;
+
+/// <summary>
+/// Background service that adds a fake notification every 8 seconds
+/// so there is something new for the polling loop to pick up.
+/// </summary>
+public class NotificationGenerator(NotificationService notifications) : BackgroundService
+{
+    private static readonly string[] Messages =
+    [
+        "Deployment to production succeeded.",
+        "CPU usage spike detected on server-03.",
+        "User 'jdoe' just signed up.",
+        "Backup completed successfully.",
+        "New comment on issue #42.",
+        "Security scan finished — no vulnerabilities found.",
+        "Disk usage on db-primary exceeded 80%.",
+        "Monthly report is ready for download.",
+    ];
+
+    private int _index;
+
+    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
+    {
+        while (!stoppingToken.IsCancellationRequested)
+        {
+            await Task.Delay(TimeSpan.FromSeconds(8), stoppingToken);
+            notifications.Add(Messages[_index % Messages.Length]);
+            _index++;
+        }
+    }
+}
